import seaborn as sns
import matplotlib.pyplot as plt
import numpy as np
import pandas as pd


sns.set(style="darkgrid", palette="colorblind")

def violinplot(data_map, title = "Experiment 1", filename = None):
    labels, data = zip(*data_map.items())

    fig, ax = plt.subplots(figsize=(14, 6))

    # Plot data
    ax = sns.violinplot(data=data, inner='box', linewidth=1.2)
    #ax.set_xticklabels(labels, fontsize = 16)
    label = [r'$K = 50$', r'$K = 100$', r'$K = 150$', r'$K = 200$', r'$K = 300$', r'$K = 400$']
    ax.set_xticklabels(label + label, fontsize = 16)
    
    colors = sns.color_palette("colorblind")
    # Set colors and hatches
    styles = [
        { 'facecolor':sns.desaturate(colors[2], 0.75)},
        { 'facecolor':sns.desaturate(colors[4], 0.75)},
        { 'facecolor':sns.desaturate(colors[9], 0.75)},
        { 'facecolor':sns.desaturate(colors[5], 0.75)},
        { 'facecolor':sns.desaturate(colors[6], 0.75)},
        { 'facecolor':sns.desaturate(colors[7], 0.75)},
        { 'facecolor':sns.desaturate(colors[2], 0.75), "hatch": "/" },
        { 'facecolor':sns.desaturate(colors[4], 0.75), "hatch": "/" },
        { 'facecolor':sns.desaturate(colors[9], 0.75), "hatch": "/" },
        { 'facecolor':sns.desaturate(colors[5], 0.75), "hatch": "/" },
        { 'facecolor':sns.desaturate(colors[6], 0.75), "hatch": "/" },
        { 'facecolor':sns.desaturate(colors[7], 0.75), "hatch": "/" },
              ]
    for violin, style in zip(ax.collections, styles):
        violin.set(**style)

    # Add line and text between prior methods and us
    split_pos = 5.5
    ax.axvline(x=split_pos, color="black", linewidth=1)
    ymin, ymax = ax.get_ylim()
    ax.text(5.45, ymin + (ymax-ymin)*0.04, "Our Folding Scheme", ha="right", va="bottom", fontsize=18, fontweight="bold")
    ax.text(3.09, ymin + (ymax-ymin)*0.042, r"$\longleftarrow$", ha="right", va="bottom", fontsize=18, fontweight="bold")
    ax.text(5.55, ymin + (ymax-ymin)*0.04, "Subsample and Aggregate", ha="left", va="bottom", fontsize=18, fontweight="bold")
    ax.text(8.52, ymin + (ymax-ymin)*0.042, r"$\longrightarrow$", ha="left", va="bottom", fontsize=18, fontweight="bold")

    # Add line for true treatment effect
    plt.axhline(0.15, color='black', linestyle='--', label=r'True treatment effect $\tau$')

    # Formatting
    plt.yticks(fontsize=18)
    plt.title(title, fontsize=20)
    plt.ylabel("Estimated treatment effect", fontsize=18)
    plt.legend(fontsize = 18)
    plt.tight_layout()
    if filename:
        plt.savefig(filename)
    plt.show()

